settings.custom_liquid:
{%- comment -%}
  ================================================================
  PAMAURA — ЛОГО ЛЕНТА "Открий ни и в"  (движеща се, реални лога)
  ================================================================
  1) Качи логата в Shopify → Content → Files → Upload files
     (точни имена): amazon.png · kaufland.png · skroutz.png · emag.png · cdiscount.png
  2) Customize → под hero-а: Add section → "Custom Liquid" → постави ЦЕЛИЯ код → Save

  Едно заглавие + движеща се лента с логата (спира при посочване).
  Логата са в Walnut brown; Amazon, Skroutz и eMAG са кликаеми и потъмняват до Cafe noir при hover.

  За добавяне/махане на лого: редактирай САМО петте реда pm_names / pm_labels /
  pm_ratios / pm_scales / pm_links по-долу (еднакъв брой и ред във всеки от тях).
  pm_ratios = ширина ÷ височина на PNG-а. pm_scales = оптична корекция на размера.
  pm_links  = 'none' за лого без линк (не оставяй празно между двете |).
  ================================================================
{%- endcomment -%}

{%- assign pm_names  = 'amazon,kaufland,skroutz,emag,cdiscount' | split: ',' -%}
{%- assign pm_labels = 'Amazon|Kaufland Global Marketplace|Skroutz|eMAG|Cdiscount' | split: '|' -%}
{%- assign pm_ratios = '3.32,3.46,4.87,3.76,6.36' | split: ',' -%}
{%- assign pm_scales = '1,1,1,.86,1' | split: ',' -%}
{%- assign pm_links  = 'https://www.amazon.co.uk/stores/Pamaura/page/121E2C4B-7540-4D26-82D5-5D143234EB06?lp_asin=B0B1J87KGQ|none|https://www.skroutz.gr/search?keyphrase=Pamaura|https://www.emag.bg/brands/brand/pamaura|none' | split: '|' -%}

<style>
  .pm-logostrip{
    --pm-linen:#F5EBE0; --pm-chamoisee:#A77A53; --pm-walnut:#5E5045; --pm-cafe:#57391F;
    --pm-line:rgba(87,57,31,.14);
    background:var(--pm-linen); padding:56px 20px;
  }
  .pm-logostrip *{box-sizing:border-box;}
  .pm-logostrip__wrap{max-width:1120px;margin:0 auto;}
  .pm-logostrip .pm-title{
    text-align:center;margin:0 0 34px;
    font-family:'Cormorant Garamond',Georgia,'Times New Roman',serif;
    font-size:clamp(24px,3.4vw,36px);font-weight:600;letter-spacing:.01em;
    color:var(--pm-cafe);
  }
  .pm-logostrip .pm-marquee{
    position:relative;overflow:hidden;
    border-top:1px solid var(--pm-line);border-bottom:1px solid var(--pm-line);
    padding:28px 0;
    -webkit-mask-image:linear-gradient(to right,transparent,#000 12%,#000 88%,transparent);
            mask-image:linear-gradient(to right,transparent,#000 12%,#000 88%,transparent);
  }
  .pm-logostrip .pm-track{display:flex;align-items:center;width:max-content;gap:clamp(44px,7vw,90px);animation:pm-scroll 42s linear infinite;}
  .pm-logostrip .pm-marquee:hover .pm-track{animation-play-state:paused;}
  .pm-logostrip .pm-logo{display:inline-flex;align-items:center;text-decoration:none;}
  .pm-logostrip .pm-mark{
    height:calc(clamp(22px,2.7vw,29px) * var(--pm-s,1));
    background-color:var(--pm-walnut);
    -webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
    -webkit-mask-position:center;mask-position:center;
    -webkit-mask-size:contain;mask-size:contain;
    opacity:.9;transition:background-color .25s ease,opacity .25s ease;
  }
  .pm-logostrip a.pm-logo:hover .pm-mark{background-color:var(--pm-cafe);opacity:1;}
  @keyframes pm-scroll{from{transform:translateX(0);}to{transform:translateX(-50%);}}
  @media (prefers-reduced-motion:reduce){
    .pm-logostrip .pm-track{animation:none;flex-wrap:wrap;justify-content:center;width:auto;row-gap:24px;}
    .pm-logostrip .pm-marquee{-webkit-mask-image:none;mask-image:none;}
  }
</style>

<section class="pm-logostrip">
  <div class="pm-logostrip__wrap">
    <h2 class="pm-title">Открий ни и в</h2>

    <div class="pm-marquee">
      <div class="pm-track">
        {%- comment -%} Логата, повторени 6 пъти за плавен безкраен цикъл {%- endcomment -%}
        {%- for pass in (1..6) -%}
          {%- for name in pm_names -%}
            {%- assign i = forloop.index0 -%}
            {%- assign url = name | append: '.png' | file_url -%}
            {%- assign link = pm_links[i] -%}
            {%- capture mark -%}<span class="pm-mark" role="img" aria-label="{{ pm_labels[i] }}" style="--pm-s:{{ pm_scales[i] }};aspect-ratio:{{ pm_ratios[i] }};-webkit-mask-image:url('{{ url }}');mask-image:url('{{ url }}');"></span>{%- endcapture -%}
            {%- if link != 'none' -%}
              <a class="pm-logo" href="{{ link }}" target="_blank" rel="noopener">{{ mark }}</a>
            {%- else -%}
              <span class="pm-logo">{{ mark }}</span>
            {%- endif -%}
          {%- endfor -%}
        {%- endfor -%}
      </div>
    </div>

    <p class="pm-note" style="text-align:center;margin:22px 0 0;font-size:12.5px;letter-spacing:.02em;color:#A77A53;">
      Открий Pamaura и в любимите ти онлайн магазини
    </p>
  </div>
</section>
